import{_ as e,o,c as a,a2 as n}from"./chunks/framework.D9E58p8B.js";const g=JSON.parse(`{"title":"When it doesn't work","description":"","frontmatter":{"title":"When it doesn't work"},"headers":[],"relativePath":"en/agent/diagnostiquer.md","filePath":"en/agent/diagnostiquer.md"}`),r={name:"en/agent/diagnostiquer.md"};function s(d,t,i,h,c,l){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="when-it-doesn-t-work" tabindex="-1">When it doesn&#39;t work <a class="header-anchor" href="#when-it-doesn-t-work" aria-label="Permalink to &quot;When it doesn&#39;t work&quot;">​</a></h1><p>Before concluding that a tool is broken, the agent must look at the state of the machine: several faults produce no error.</p><h2 id="what-you-ask" tabindex="-1">What you ask <a class="header-anchor" href="#what-you-ask" aria-label="Permalink to &quot;What you ask&quot;">​</a></h2><blockquote><p>&quot;Daimon doesn&#39;t seem to do anything: find out why.&quot;</p></blockquote><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><p>It calls <a href="/Daimon/en/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>, <strong>first</strong>. A single call returns the state of each organ, without ever opening a dialog. What it reads:</p><table tabindex="0"><thead><tr><th>Key</th><th>What it tells</th></tr></thead><tbody><tr><td><code>permissions</code></td><td>Which system permission is missing</td></tr><tr><td><code>consequences</code></td><td>What that absence concretely does to each tool</td></tr><tr><td><code>ceiling</code></td><td>The active ceiling</td></tr><tr><td><code>exclusions</code></td><td>The state of your exclusions file</td></tr><tr><td><code>overlay</code></td><td>Whether the process that draws the markers is alive</td></tr><tr><td><code>cannot_detect</code></td><td>What the diagnostic <strong>cannot</strong> see: an absence of problem there is not proof</td></tr><tr><td><code>next</code></td><td>The suggested next steps</td></tr></tbody></table><h2 id="the-most-common-symptoms" tabindex="-1">The most common symptoms <a class="header-anchor" href="#the-most-common-symptoms" aria-label="Permalink to &quot;The most common symptoms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Probable cause</th></tr></thead><tbody><tr><td>An action answers <code>done</code> with no effect</td><td><strong>Accessibilité</strong> (Accessibility) permission missing</td></tr><tr><td>An action waits 30 seconds</td><td><strong>Accessibilité</strong> permission missing, or confirmation pending</td></tr><tr><td>Captures fail</td><td><strong>Enregistrement de l&#39;écran</strong> (Screen Recording) permission missing</td></tr><tr><td>An action is <code>refused</code></td><td>Above the ceiling, or confirmation not obtained</td></tr><tr><td>A capture is refused or blacked out</td><td>An application or area in your exclusions</td></tr><tr><td>The markers do not appear</td><td><strong>Présence à l&#39;écran</strong> (On-screen presence) turned off</td></tr><tr><td>The agent sees no Daimon tool</td><td>Daimon not registered in this agent, or agent not restarted</td></tr></tbody></table><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>A named cause and the steps to follow. For causes that depend on your settings, the <a href="/Daimon/en/guide/depannage.html">Troubleshooting</a> page gives the user-side detail.</p><h2 id="reporting-a-problem" tabindex="-1">Reporting a problem <a class="header-anchor" href="#reporting-a-problem" aria-label="Permalink to &quot;Reporting a problem&quot;">​</a></h2><p>If <code>daimon_doctor</code> does not explain it, <a href="https://github.com/ArboRithm/Daimon/issues" target="_blank" rel="noreferrer">open an issue</a> with its output.</p>',13)])])}const u=e(r,[["render",s]]);export{g as __pageData,u as default};
